insert into public.quiz_questions
  (ord, prompt, options, correct_index, difficulty, time_limit_seconds, explanation)
values
  (1, 'Como uma rede social aprende quais conteúdos mostrar para você?', '["Lendo seus pensamentos", "Observando sinais como cliques, curtidas, tempo de visualização e buscas", "Perguntando a seus amigos todos os dias", "Escolhendo sempre o conteúdo mais antigo"]'::jsonb, 1, 'easy', 15, 'Algoritmos usam sinais do seu comportamento para estimar o que pode prender sua atenção.'),
  (2, 'O que pode acontecer quando você passa muito tempo olhando um tipo de vídeo?', '["O aplicativo pode recomendar mais vídeos parecidos", "A conta é apagada automaticamente", "O celular deixa de receber mensagens", "A senha muda sozinha"]'::jsonb, 0, 'easy', 15, 'O histórico de interação ajuda o algoritmo a personalizar recomendações.'),
  (3, 'Qual é um risco de um algoritmo saber demais sobre seus hábitos?', '["Ele pode usar seus interesses para influenciar escolhas e anúncios", "Ele melhora a bateria do celular", "Ele impede qualquer anúncio", "Ele torna todas as contas anônimas"]'::jsonb, 0, 'easy', 15, 'Quanto mais dados uma plataforma reúne, mais consegue prever e influenciar preferências.'),
  (4, 'Qual atitude reduz a quantidade de dados pessoais expostos nas redes sociais?', '["Publicar endereço e rotina diariamente", "Aceitar todos os seguidores", "Revisar privacidade e compartilhar apenas o necessário", "Usar a mesma senha em todos os aplicativos"]'::jsonb, 2, 'easy', 15, 'Configurações de privacidade e exposição mínima reduzem riscos.'),
  (5, 'Qual senha é mais resistente a tentativas de adivinhação?', '["123456789", "nomeescola2024", "bolo-violeta-trem-72", "qwerty123"]'::jsonb, 2, 'easy', 15, 'Uma frase longa com palavras aleatórias é mais forte que uma sequência previsível.'),
  (6, 'Por que não é recomendado reutilizar a mesma senha?', '["Porque o celular fica mais lento", "Porque um vazamento pode abrir acesso a várias contas", "Porque a senha deixa de ter letras", "Porque sites bloqueiam senhas repetidas"]'::jsonb, 1, 'easy', 15, 'Senhas únicas limitam o impacto quando um serviço sofre vazamento.'),
  (7, 'O que é autenticação em dois fatores (2FA)?', '["Digitar a mesma senha duas vezes", "Usar duas contas ao mesmo tempo", "Adicionar uma segunda prova de identidade além da senha", "Trocar a senha a cada duas horas"]'::jsonb, 2, 'easy', 15, 'A segunda etapa pode ser um código de aplicativo, uma chave ou uma biometria.'),
  (8, 'Qual segunda etapa é mais resistente a um golpe de troca de chip?', '["Código enviado por SMS", "Aplicativo autenticador ou chave de segurança", "Nome do animal de estimação", "Pergunta publicada no perfil"]'::jsonb, 1, 'medium', 20, 'Aplicativos autenticadores e chaves não dependem da linha telefônica.'),
  (9, 'Você recebe um link urgente dizendo que sua conta escolar será bloqueada. O que fazer?', '["Clicar imediatamente", "Encaminhar para a turma", "Abrir o site pelo aplicativo ou endereço oficial", "Responder enviando sua senha"]'::jsonb, 2, 'medium', 20, 'Acesse o serviço por um caminho conhecido, sem usar o link recebido.'),
  (10, 'Qual é um sinal comum de phishing?', '["Mensagem com urgência, pedido de dados e endereço estranho", "Mensagem sem nenhuma imagem", "Mensagem recebida durante o dia", "Mensagem com pontuação correta"]'::jsonb, 0, 'medium', 20, 'Urgência e pressão para agir são técnicas frequentes de golpes.'),
  (11, 'O que é engenharia social?', '["Um tipo de cabo de rede", "Manipulação de pessoas para obter dados ou acesso", "Uma atualização do sistema", "Um método para aumentar o sinal Wi-Fi"]'::jsonb, 1, 'medium', 20, 'O atacante explora confiança, medo, autoridade ou pressa em vez de atacar apenas a tecnologia.'),
  (12, 'Uma pessoa pede por telefone o código que acabou de chegar no seu celular. Qual resposta é segura?', '["Informar o código só para ela", "Informar metade do código", "Nunca compartilhar o código e confirmar o contato por canal oficial", "Publicar o código para pedir ajuda"]'::jsonb, 2, 'medium', 20, 'Códigos de autenticação são secretos e podem permitir acesso à conta.'),
  (13, 'O cadeado HTTPS no navegador significa que:', '["O site é sempre confiável", "A conexão é criptografada, mas o site ainda pode ser falso", "O site pertence ao governo", "Não existem anúncios ou golpes"]'::jsonb, 1, 'medium', 20, 'HTTPS protege a conexão; não confirma sozinho a identidade ou honestidade do site.'),
  (14, 'O que fazer ao encontrar um pen drive desconhecido na escola?', '["Conectá-lo para descobrir o dono", "Usá-lo em qualquer computador", "Entregá-lo à direção sem conectá-lo", "Copiar os arquivos para o celular"]'::jsonb, 2, 'medium', 20, 'Mídias desconhecidas podem conter arquivos maliciosos.'),
  (15, 'O que é ransomware?', '["Um programa que organiza fotos", "Um golpe que criptografa arquivos e exige resgate", "Uma proteção contra vírus", "Uma rede social escolar"]'::jsonb, 1, 'hard', 25, 'Backups, atualizações e cuidado com anexos ajudam a reduzir o impacto.'),
  (16, 'O que significa verificar uma senha no Have I Been Pwned?', '["Descobrir a senha de outra pessoa", "Verificar se uma senha apareceu em vazamentos conhecidos", "Criar uma senha automaticamente", "Bloquear todos os sites"]'::jsonb, 1, 'hard', 25, 'O serviço informa ocorrências conhecidas de vazamento; ele não deve receber sua senha em texto puro.'),
  (17, 'Por que uma checagem segura de senha usa apenas parte do hash?', '["Para tornar a senha pública", "Para evitar enviar a senha inteira ao serviço de consulta", "Para diminuir o tamanho da senha", "Para permitir que qualquer pessoa veja a senha"]'::jsonb, 1, 'hard', 25, 'O modelo de k-anonimato reduz a exposição: a senha permanece no dispositivo.'),
  (18, 'Se uma senha apareceu em um vazamento, qual é a melhor ação?', '["Continuar usando se ninguém descobriu", "Trocar a senha e também atualizar contas que reutilizavam a mesma", "Publicar a senha para alertar amigos", "Adicionar apenas um número no final"]'::jsonb, 1, 'hard', 25, 'Troque por uma senha única e ative 2FA sempre que possível.'),
  (19, 'Qual comportamento ajuda a reduzir uma bolha de recomendações?', '["Interagir apenas com um tipo de opinião", "Conferir fontes diferentes e buscar assuntos variados", "Compartilhar tudo sem ler", "Desativar todas as atualizações de segurança"]'::jsonb, 1, 'hard', 25, 'Comparar fontes e perspectivas evita depender de uma única seleção algorítmica.'),
  (20, 'Qual combinação oferece a melhor proteção para uma conta escolar?', '["Senha única e longa, 2FA e atenção a links", "Senha curta reutilizada e login automático em qualquer computador", "Código de autenticação compartilhado com colegas", "Mesma senha para e-mail, rede social e banco"]'::jsonb, 0, 'hard', 25, 'Segurança funciona melhor em camadas: senha forte, segundo fator e atenção contra golpes.')
